    if (b == 0) return a;
    return ggt(b, a % b);
}

long long lcm_ll(long long a, long long b) {
    return a / ggt(a, b) * b;
}

int gcdRange(long long n) {
    long long gcd = 1;
    for (long long i = 1; i <= n; i++) {
        gcd = lcm_ll(gcd, i);
    }
    return (int)gcd;
}

void init(long long n, int k) {
    pw.assign(k, 0);
    pw[0] = 1;
    for (int i = 1; i < k; i++) {
        pw[i] = (n * pw[i - 1]) % MOD;
    }
}

